// Coverage scope shared by every collector (vitest, playwright client, SSR server) and the merge
// script, so that all sources resolve to the same `src/...` path and can be merged.
import path from 'node:path';
import { COVERAGE_DIR } from './constants.mjs';

const EXCLUDED = [
	// generated by typesafe-i18n
	/(^|\/)src\/i18n\/i18n-[^/]+\.ts$/,
	// pure data (topojson / maplibre style json)
	/(^|\/)src\/lib\/stores\/map(Data|Style)\.ts$/,
	// vendored shadcn-svelte components and data-table helpers
	/(^|\/)src\/lib\/components\/(ui|table)\//,
	// the empty `$lib` placeholder of the SvelteKit template
	/(^|\/)src\/lib\/index\.ts$/,
	// design notes of the api (apiSchema.ts is not imported anywhere)
	/(^|\/)src\/lib\/schemas\//,
	// helpers of the tests themselves
	/(^|\/)src\/lib\/test-utils\//,
	/\.d\.ts$/,
	// css coverage of the component tests (`import './app.css'`)
	/\.css$/,
	/\.(test|spec)\.(js|ts)$/
];

/**
 * Sourcemap paths are often relative (`../../../src/x.ts`, `../node_modules/.pnpm/d3/src/x.js`),
 * which globs do not match reliably – hence a function. Dependencies have `src/` dirs too.
 */
/** @param {string} filePath */
export const sourceFilter = (filePath) => {
	const p = filePath.replaceAll('\\', '/');
	if (p.includes('node_modules') || !/(^|\/)src\//.test(p)) return false;
	return !EXCLUDED.some((re) => re.test(p));
};

/**
 * normalise e.g. `../../../src/lib/x.ts` or `/abs/repo/src/lib/x.ts` to `src/lib/x.ts`.
 * MCR applies this *before* the filters, so dependencies must keep their path.
 */
/** @param {string} filePath */
export const sourcePath = (filePath) => {
	// strip vite query suffixes like `?sentry-auto-wrap`
	const p = filePath.replaceAll('\\', '/').replace(/\?.*$/, '');
	if (p.includes('node_modules')) return p;
	const idx = p.lastIndexOf('src/');
	return idx === -1 ? p : p.slice(idx);
};

/** final safety net on the normalised paths: only app sources make it into the report */
/** @param {{ sourcePath: string }} file */
export const outputFilter = (file) =>
	file.sourcePath.startsWith('src/') && sourceFilter(file.sourcePath);

/** @type {import('monocart-coverage-reports').CoverageReportOptions} */
export const e2eClientCoverageOptions = {
	name: 'e2e client coverage',
	outputDir: path.join(COVERAGE_DIR, 'e2e'),
	reports: [['raw', { outputDir: 'raw' }]],
	entryFilter: (entry) => entry.url.includes('/_app/immutable/'),
	sourceFilter,
	sourcePath,
	logging: 'error'
};

export const SERVER_V8_COVERAGE_DIR = path.join(COVERAGE_DIR, 'server-v8');
